module benchmark/solution

import std/env (getArgs)
import std/fs (readFile)
import std/string (split, trim, stringToInt)
import std/list (foldl)

pure func parseNum(line: string) -> int =
  match stringToInt(trim(line)) {
    Some(n) => n,
    None => 0
  }

pure func sumLines(content: string) -> int =
  foldl(func(acc: int, line: string) -> int { acc + parseNum(line) }, 0, split(content, "\n"))

export func main() -> () ! {IO, FS, Env} {
  match getArgs() {
    filename :: _ => println(show(sumLines(readFile(filename)))),
    [] => println("Usage: solution <filename>")
  }
}

